'use strict'

import resource from '../../resource'
import { ENEMY_ARMOS, DIRECTION_NORTH } from '../../constant'
import { drawImage } from './common'
import { Walker } from './walker'

// The Armos, as measured in the ROM (object $1E, bank 4 $8CC7): a statue Link touches comes alive on its
// square, stands still about 50 frames, then walks the grid like a Moblin, without shooting, slowly
// (0.5 NES pixel a frame) or fast (1.5), half the time each ($03BC: $20 or $60). Always red, 3 points of
// life, one heart at contact (see WALKERS)
export const ARMOS_WAKE_STEPS = 50
const SLOW_SPEED = 1
const FAST_SPEED = 3
const STATE_WAKING = 'waking'
const WALK_FRAME_PIXELS = 8

export class Armos extends Walker {
  constructor (x, y, random = Math.random) {
    super(ENEMY_ARMOS, x, y, DIRECTION_NORTH, random)
    this.speed = random() < 0.5 ? SLOW_SPEED : FAST_SPEED
    this.setState(STATE_WAKING)
  }

  act (map) {
    if (this.state === STATE_WAKING) {
      if (this.steps >= ARMOS_WAKE_STEPS) {
        this.start(map)
      }
      return
    }
    super.act(map)
  }

  // It only has a front and a back: the front when it goes sideways
  drawBody (context) {
    const frame = Math.floor(this.walkedPixels / WALK_FRAME_PIXELS) % 2
    const side = this.direction === DIRECTION_NORTH ? 'north' : 'south'
    drawImage(context, resource.getSprite(`armos_${side}_move`), frame, this.x, this.y, this.width, this.height)
  }
}
